<?php namespace App\Services;
use App\Models\{Source,Entry};use Illuminate\Support\Facades\Http;use Illuminate\Support\Str;
class Importer {
 // RSS hosts must be explicitly allowlisted by deployment operator; no redirects or arbitrary crawler.
 public function run(Source $s): int {if($s->driver==='adzuna'){if(!config('obm.adzuna_id')||!config('obm.adzuna_key'))throw new \RuntimeException('Adzuna credentials missing');$country=strtolower($s->country);if(!preg_match('/^[a-z]{2}$/D',$country))throw new \RuntimeException('Invalid country');$response=Http::timeout(20)->withoutRedirecting()->get('https://api.adzuna.com/v1/api/jobs/'.$country.'/search/1',['app_id'=>config('obm.adzuna_id'),'app_key'=>config('obm.adzuna_key'),'results_per_page'=>50])->throw();$items=[];foreach($response->json('results',[]) as $x)$items[]=['title'=>$x['title']??'','url'=>$x['redirect_url']??'','summary'=>$x['description']??'','city'=>$x['location']['display_name']??null,'details'=>['company'=>$x['company']['display_name']??null,'salary_min'=>$x['salary_min']??null,'salary_max'=>$x['salary_max']??null]];}else{$host=parse_url($s->url,PHP_URL_HOST);if(parse_url($s->url,PHP_URL_SCHEME)!=='https'||!in_array($host,config('obm.rss_hosts',[]),true))throw new \RuntimeException('RSS host not allowlisted');$res=Http::timeout(20)->withoutRedirecting()->get($s->url)->throw();if(strlen($res->body())>2000000)throw new \RuntimeException('Feed too large');$xml=simplexml_load_string($res->body(),'SimpleXMLElement',LIBXML_NONET|LIBXML_NOERROR|LIBXML_NOWARNING);if(!$xml)throw new \RuntimeException('Invalid XML');$items=[];foreach($xml->channel->item??$xml->entry??[] as $x){$link=(string)$x->link;if(!$link)$link=(string)$x->link['href'];$items[]=['title'=>(string)$x->title,'url'=>$link,'summary'=>(string)($x->description??$x->summary??'')];if(count($items)>=100)break;}}
 $count=0;foreach($items as $x){if(!filter_var($x['url'],FILTER_VALIDATE_URL)||!in_array(parse_url($x['url'],PHP_URL_SCHEME),['http','https'])||!trim($x['title']))continue;$fp=hash('sha256',$s->type.'|'.$x['url']);$e=Entry::firstOrNew(['fingerprint'=>$fp]);if(!$e->exists){$e->fill(['source_id'=>$s->id,'type'=>$s->type,'slug'=>Str::limit(Str::slug(strip_tags($x['title'])),150,'').'-'.substr($fp,0,16),'title'=>Str::limit(strip_tags($x['title']),250,''),'summary'=>Str::limit(strip_tags($x['summary']),1500,''),'url'=>$x['url'],'country'=>$s->country,'city'=>isset($x['city'])?Str::limit($x['city'],100,''):null,'details'=>$x['details']??null,'status'=>'pending','expires_at'=>$s->type==='job'?now()->addDays(14):null]);}$e->last_seen=now();$e->save();$count++;}return $count;
 }
}
